import json
d=json.load(open('/tmp/roadmap.json'))
items=d['items'] if isinstance(d,dict) else d
by={i['id']:i for i in items}
kids={}
for i in items: kids.setdefault(i.get('parent') or '',[]).append(i)
OPEN={'pending','active','blocked'}
def sub(pid):
    out=[]
    st=[pid]
    while st:
        c=st.pop()
        for k in kids.get(c,[]):
            out.append(k); st.append(k['id'])
    return out
print('=== AJCR.w4-rep subtree: parent/child disagreements ===')
for i in items:
    if not i['id'].startswith('AJCR.w4-rep'): continue
    ch=kids.get(i['id'],[])
    if not ch: continue
    cs=[c['status'] for c in ch]
    par=i['status']
    terminal={'done','rejected'}
    if all(c in terminal for c in cs) and par not in terminal:
        print(' MISMATCH-A', i['id'],'=',par,'but ALL children terminal:',cs)
    if par in terminal and any(c in OPEN for c in cs):
        print(' MISMATCH-B', i['id'],'=',par,'but open children:',[c['id'] for c in ch if c['status'] in OPEN])
    if par=='active' and not any(c=='active' for c in cs):
        print(' NO-ACTIVE-CHILD', i['id'],'= active; children:', {c['id'].split('.')[-1]:c['status'] for c in ch})
    if par=='blocked' and any(c=='active' for c in cs):
        print(' BLOCKED-WITH-ACTIVE-CHILD', i['id'], {c['id'].split('.')[-1]:c['status'] for c in ch})
print()
print('=== active spine check ===')
for i in items:
    if i['status']!='active': continue
    p=i.get('parent'); chain=[i['id']]
    while p: chain.append(p); p=by[p].get('parent')
    print(' ', i['id'], ' <- chain:', ' <- '.join(chain[1:]) or '(root)')
